/* Design tokens mirroring the BMW corporate web system (bmw.com):
   white canvas, #262626 ink, one blue for actions (#1c69d4, pressed #0653b6),
   warm-navy dark bands (#1a2129), 1px #e6e6e6 hairlines, 0px corners, no shadows,
   700 display paired with 300 body. BMW Type Next is a licensed face and is not
   used here; Barlow (SIL OFL, self-hosted) stands in for it. */

:root {
  /* surfaces */
  --canvas: #ffffff;
  --surface-soft: #f7f7f7;
  --surface-card: #fafafa;
  --surface-strong: #ebebeb;
  --surface-dark: #1a2129;
  --surface-dark-2: #262e38;

  /* hairlines */
  --hairline: #e6e6e6;
  --hairline-strong: #cccccc;

  /* text */
  --ink: #262626;
  --body: #3c3c3c;
  --body-strong: #1a1a1a;
  --muted: #6b6b6b;
  --muted-soft: #9a9a9a;
  --on-dark: #ffffff;
  --on-dark-soft: #bbbbbb;

  /* action */
  --primary: #1c69d4;
  --primary-active: #0653b6;
  --primary-disabled: #d6d6d6;
  --focus: #1c69d4;

  /* data: diverging blue <-> red with a grey midpoint (validated on #ffffff) */
  --div-red-strong: #c4302b;
  --div-red-light: #e8877c;
  --div-mid: #a3a3a3;
  --div-blue-light: #7aa7e6;
  --div-blue-strong: #1c69d4;
  --data-blue: #1c69d4;
  --data-blue-track: #e3edfa;
  --grid: #ebebeb;

  /* status (always with a label) */
  --status-error: #c4302b;

  /* type */
  --font: "Barlow", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --fs-display-xl: 64px;
  --fs-display-lg: 48px;
  --fs-display-md: 32px;
  --fs-display-sm: 24px;
  --fs-title-lg: 20px;
  --fs-title-md: 18px;
  --fs-title-sm: 16px;
  --fs-body: 16px;
  --fs-body-sm: 14px;
  --fs-caption: 12px;

  /* spacing (8px base) */
  --s-1: 4px;
  --s-2: 8px;
  --s-3: 12px;
  --s-4: 16px;
  --s-5: 24px;
  --s-6: 32px;
  --s-7: 48px;
  --s-8: 80px;

  --max: 1440px;
  --gutter: 48px;
  --nav-h: 64px;
}

@media (max-width: 1024px) {
  :root { --gutter: 32px; }
}

@media (max-width: 767px) {
  :root {
    --gutter: 16px;
    --fs-display-xl: 40px;
    --fs-display-lg: 32px;
    --fs-display-md: 26px;
    --s-8: 48px;
  }
}

*,
*::before,
*::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--canvas);
  color: var(--body);
  font-family: var(--font);
  font-size: var(--fs-body);
  font-weight: 300;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4 { color: var(--ink); font-weight: 700; margin: 0; letter-spacing: 0; }
h1 { font-size: var(--fs-display-xl); line-height: 1.05; }
h2 { font-size: var(--fs-display-md); line-height: 1.15; }
h3 { font-size: var(--fs-title-lg); line-height: 1.3; }
h4 { font-size: var(--fs-title-sm); line-height: 1.4; }
p { margin: 0; }
strong { font-weight: 700; color: var(--body-strong); }
a { color: inherit; }
button, input, select, textarea { font: inherit; color: inherit; }
table { border-collapse: collapse; width: 100%; }

:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; animation: none !important; }
}

.num { font-variant-numeric: tabular-nums; }

/* ------------------------------------------------------------------ layout */
.wrap { max-width: var(--max); margin: 0 auto; padding: 0 var(--gutter); }
.band { padding: var(--s-8) 0; }
.band--soft { background: var(--surface-soft); }
.band--dark { background: var(--surface-dark); color: var(--on-dark-soft); }
.band--dark h1, .band--dark h2, .band--dark h3 { color: var(--on-dark); }
.band--tight { padding: var(--s-7) 0; }
.stack > * + * { margin-top: var(--s-4); }
.stack-lg > * + * { margin-top: var(--s-6); }
.row { display: flex; gap: var(--s-4); align-items: center; flex-wrap: wrap; }
.spread { display: flex; justify-content: space-between; gap: var(--s-4); align-items: baseline; flex-wrap: wrap; }
.lead { font-size: var(--fs-title-md); line-height: 1.5; color: var(--body); max-width: 72ch; }
.band--dark .lead { color: var(--on-dark-soft); }
.muted { color: var(--muted); }
.small { font-size: var(--fs-body-sm); }
.caption { font-size: var(--fs-caption); font-weight: 400; letter-spacing: 0.5px; color: var(--muted); }
.measure { max-width: 72ch; }

/* ------------------------------------------------------------------ nav */
.nav {
  position: sticky; top: 0; z-index: 20;
  background: var(--canvas); border-bottom: 1px solid var(--hairline);
  height: var(--nav-h);
}
.nav__inner { height: 100%; display: flex; align-items: center; gap: var(--s-6); }
.brand { display: flex; align-items: baseline; gap: var(--s-3); text-decoration: none; color: var(--ink); white-space: nowrap; }
.brand__mark { font-weight: 700; font-size: 20px; letter-spacing: 1px; }
.brand__name { font-weight: 400; font-size: var(--fs-body-sm); color: var(--body); }
.nav__links { display: flex; gap: var(--s-5); height: 100%; overflow-x: auto; scrollbar-width: none; }
.nav__links a {
  display: flex; align-items: center; height: 100%;
  font-size: var(--fs-body-sm); font-weight: 400; letter-spacing: 0.3px;
  color: var(--muted); text-decoration: none; border-bottom: 2px solid transparent; white-space: nowrap;
}
.nav__links a:hover { color: var(--ink); }
.nav__links a.active { color: var(--ink); border-bottom-color: var(--ink); }
.nav__meta { margin-left: auto; white-space: nowrap; }
@media (max-width: 900px) {
  .brand__name { display: none; }
  .nav__meta { display: none; }
  .nav__inner { gap: var(--s-4); }
}

/* ------------------------------------------------------------------ buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--s-2);
  min-height: 48px; padding: 14px 32px; border: 0; border-radius: 0; cursor: pointer;
  font-size: 14px; font-weight: 700; letter-spacing: 0.5px; text-transform: uppercase; line-height: 1;
  background: var(--primary); color: #fff; text-decoration: none;
}
.btn:hover { background: var(--primary-active); }
.btn:active { background: var(--primary-active); }
.btn:disabled { background: var(--primary-disabled); color: var(--muted); cursor: not-allowed; }
.btn--secondary { background: var(--canvas); color: var(--ink); border: 1px solid var(--hairline-strong); padding: 13px 31px; }
.btn--secondary:hover { background: var(--surface-soft); border-color: var(--ink); }
.btn--on-dark { background: transparent; color: #fff; border: 1px solid #fff; padding: 13px 31px; }
.btn--on-dark:hover { background: var(--surface-dark-2); }
.btn--small { min-height: 36px; padding: 8px 16px; font-size: 13px; }
.textlink {
  background: none; border: 0; padding: 0; cursor: pointer; color: var(--ink);
  font-size: 13px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; text-decoration: none;
}
.textlink::after { content: " ›"; }
.textlink:hover { color: var(--primary); }

/* ------------------------------------------------------------------ inputs */
.field { display: flex; flex-direction: column; gap: var(--s-2); }
.field label, .label { font-size: var(--fs-body-sm); font-weight: 400; color: var(--body); }
.input, .select, .textarea {
  min-height: 48px; padding: 14px 16px; border: 1px solid var(--hairline); border-radius: 0;
  background: var(--canvas); color: var(--ink); font-weight: 300; width: 100%;
}
.input:focus, .select:focus, .textarea:focus { outline: none; border: 1px solid var(--ink); box-shadow: inset 0 0 0 1px var(--ink); }
.textarea { min-height: 96px; resize: vertical; line-height: 1.5; }
.select { appearance: none; background-image: linear-gradient(45deg, transparent 50%, var(--ink) 50%), linear-gradient(135deg, var(--ink) 50%, transparent 50%); background-position: calc(100% - 20px) 21px, calc(100% - 15px) 21px; background-size: 5px 5px; background-repeat: no-repeat; padding-right: 40px; }

/* ------------------------------------------------------------------ chips & tabs */
.chips { display: flex; gap: var(--s-2); flex-wrap: wrap; }
.chip {
  border: 1px solid var(--hairline-strong); background: var(--canvas); color: var(--ink);
  padding: 8px 14px; font-size: var(--fs-caption); font-weight: 400; letter-spacing: 0.5px; cursor: pointer; border-radius: 0;
}
.chip:hover { border-color: var(--ink); }
.chip[aria-pressed="true"] { background: var(--ink); color: #fff; border-color: var(--ink); }
.band--dark .chip { background: transparent; color: #fff; border-color: #5b6470; }
.band--dark .chip:hover { border-color: #fff; }
.tabs { display: flex; gap: var(--s-5); border-bottom: 1px solid var(--hairline); overflow-x: auto; }
.tab {
  background: none; border: 0; border-bottom: 2px solid transparent; padding: 12px 0; cursor: pointer; white-space: nowrap;
  font-size: 13px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--muted);
}
.tab:hover { color: var(--ink); }
.tab[aria-selected="true"] { color: var(--ink); border-bottom-color: var(--ink); }

/* ------------------------------------------------------------------ option tiles (configurator) */
.tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: var(--s-3); }
.tile {
  text-align: left; background: var(--canvas); border: 1px solid var(--hairline); padding: 16px 24px; cursor: pointer;
  display: flex; flex-direction: column; gap: var(--s-1); border-radius: 0; color: var(--body);
}
.tile:hover { border-color: var(--hairline-strong); }
.tile[aria-pressed="true"] { border: 2px solid var(--primary); padding: 15px 23px; }
.tile__title { font-weight: 700; color: var(--ink); font-size: var(--fs-title-sm); line-height: 1.3; }

/* ------------------------------------------------------------------ spec cells */
.specs { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); border-top: 1px solid var(--hairline); }
.spec { padding: var(--s-5) var(--s-5) var(--s-5) 0; border-bottom: 1px solid var(--hairline); }
.spec + .spec { padding-left: var(--s-5); border-left: 1px solid var(--hairline); }
.spec__value { font-size: var(--fs-display-sm); font-weight: 700; color: var(--ink); line-height: 1.25; }
.spec__label { font-size: var(--fs-body-sm); color: var(--muted); }
@media (max-width: 767px) { .spec + .spec { border-left: 0; padding-left: 0; } }

/* ------------------------------------------------------------------ tables */
.table-scroll { overflow-x: auto; border-top: 1px solid var(--hairline); }
.table th, .table td { padding: 12px 16px 12px 0; text-align: left; border-bottom: 1px solid var(--hairline); vertical-align: top; font-size: var(--fs-body-sm); }
.table th { font-weight: 400; color: var(--muted); font-size: var(--fs-caption); letter-spacing: 0.5px; white-space: nowrap; }
.table th button { background: none; border: 0; padding: 0; color: inherit; font: inherit; cursor: pointer; letter-spacing: inherit; }
.table th button:hover { color: var(--ink); }
.table td.r, .table th.r { text-align: right; }
.table tbody tr.clickable { cursor: pointer; }
.table tbody tr.clickable:hover td { background: var(--surface-soft); }
.table td strong { font-weight: 700; }

/* ------------------------------------------------------------------ markers */
.verdict { display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-body-sm); font-weight: 400; color: var(--ink); white-space: nowrap; }
.verdict__mark { width: 10px; height: 10px; flex: none; }
.rec { display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-body-sm); font-weight: 700; color: var(--ink); white-space: nowrap; }
.rec__mark { width: 12px; height: 12px; flex: none; border: 2px solid var(--primary); }
.rec--prioritise .rec__mark { background: var(--primary); }
.rec--consider .rec__mark { background: var(--data-blue-track); }
.rec--low .rec__mark { border-color: var(--muted-soft); background: var(--surface-strong); }
.rec--insufficient .rec__mark { border: 2px dashed var(--muted-soft); }
.rec--notsold .rec__mark { border: 2px solid var(--hairline); }
.rec--insufficient, .rec--notsold { font-weight: 400; color: var(--muted); }
.fit { font-size: 15px; line-height: 1; }

/* ------------------------------------------------------------------ notes & states */
.note { border-left: 2px solid var(--ink); padding: var(--s-2) 0 var(--s-2) var(--s-4); font-size: var(--fs-body-sm); color: var(--body); max-width: 80ch; }
.note--warn { border-left-color: var(--div-red-strong); }
.band--dark .note { border-left-color: #fff; color: var(--on-dark-soft); }
.state { padding: var(--s-7) 0; color: var(--muted); }
.error { color: var(--status-error); font-weight: 400; }
.skeleton { background: var(--surface-soft); height: 16px; margin: 8px 0; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.divider { border: 0; border-top: 1px solid var(--hairline); margin: 0; }
details > summary { cursor: pointer; font-size: var(--fs-body-sm); color: var(--ink); font-weight: 400; }
details > summary:hover { color: var(--primary); }
.quote { border-left: 2px solid var(--hairline-strong); padding-left: var(--s-4); font-size: var(--fs-body-sm); }
.quote p { color: var(--body-strong); font-weight: 300; }
.kv { display: grid; grid-template-columns: max-content 1fr; gap: 4px 16px; font-size: var(--fs-body-sm); }
.kv dt { color: var(--muted); }
.kv dd { margin: 0; color: var(--ink); }

/* ------------------------------------------------------------------ footer */
.footer { background: var(--surface-soft); padding: var(--s-7) 0; font-size: var(--fs-body-sm); color: var(--body); margin-top: var(--s-8); }

import { useEffect, useState } from "react";

// All data comes from the FastAPI backend (bmw_feedback/api.py); nothing is hard-coded here.
export async function getJSON<T>(path: string): Promise<T> {
  const res = await fetch(path);
  if (!res.ok) throw new Error(`${res.status} ${res.statusText}: ${await res.text()}`);
  return res.json() as Promise<T>;
}

export async function postJSON<T>(path: string, body: unknown): Promise<T> {
  const res = await fetch(path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    let detail = res.statusText;
    try {
      const j = await res.json();
      detail = typeof j.detail === "string" ? j.detail : JSON.stringify(j.detail);
    } catch {
      /* keep status text */
    }
    throw new Error(detail);
  }
  return res.json() as Promise<T>;
}

export function useApi<T>(path: string | null) {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(Boolean(path));
  useEffect(() => {
    if (!path) return;
    let live = true;
    setLoading(true);
    setError(null);
    getJSON<T>(path)
      .then((d) => live && setData(d))
      .catch((e: Error) => live && setError(e.message))
      .finally(() => live && setLoading(false));
    return () => {
      live = false;
    };
  }, [path]);
  return { data, error, loading };
}

export const fmtInt = (v: number | null | undefined) =>
  v === null || v === undefined ? "–" : Math.round(v).toLocaleString("en-GB");
export const fmtNum = (v: number | null | undefined, d = 2) =>
  v === null || v === undefined || Number.isNaN(v) ? "–" : v.toFixed(d);
export const fmtEur = (v: number | null | undefined) =>
  v === null || v === undefined ? "–" : `EUR ${Math.round(v).toLocaleString("en-GB")}`;
export const fmtPct = (v: number | null | undefined, d = 0) =>
  v === null || v === undefined ? "–" : `${(v * 100).toFixed(d)}%`;
export const compact = (v: number) =>
  v >= 1_000_000 ? `${(v / 1_000_000).toFixed(1)}M` : v >= 1000 ? `${Math.round(v / 1000)}K` : `${v}`;

export const MODEL_NAMES: Record<string, string> = {
  F70: "1 Series",
  G60: "5 Series",
  G70: "7 Series",
};
export const MARKET_NAMES: Record<string, string> = {
  EU: "Europe",
  US: "United States",
  CN: "China",
  RoW: "Rest of world",
};

import { fmtNum } from "../api";

// Verdicts use a validated diverging scale: red = more complaints than expected,
// blue = fewer, grey = as expected. The label always accompanies the colour.
const VERDICT_COLORS: Record<string, string> = {
  Bad: "var(--div-red-strong)",
  "Leaning bad": "var(--div-red-light)",
  Mixed: "var(--div-mid)",
  "Leaning good": "var(--div-blue-light)",
  Good: "var(--div-blue-strong)",
  "Not enough data": "transparent",
};

export function Verdict({ verdict }: { verdict: string }) {
  const empty = verdict === "Not enough data";
  return (
    <span className="verdict">
      <span
        className="verdict__mark"
        style={{ background: VERDICT_COLORS[verdict] ?? "transparent", border: empty ? "1px dashed var(--muted-soft)" : "none" }}
        aria-hidden
      />
      {verdict}
    </span>
  );
}

const REC_CLASS: Record<string, string> = {
  Prioritise: "rec--prioritise",
  Consider: "rec--consider",
  "Low priority": "rec--low",
  "Insufficient evidence": "rec--insufficient",
  "Not sold": "rec--notsold",
};

export function Recommendation({ value }: { value: string }) {
  return (
    <span className={`rec ${REC_CLASS[value] ?? ""}`}>
      <span className="rec__mark" aria-hidden />
      {value}
    </span>
  );
}

// Price-list fitment in the PDFs' own notation: ■ standard, □ optional.
const TIER_TEXT: Record<string, [string, string]> = {
  standard_all: ["■", "Standard on all covered variants"],
  standard_some: ["■□", "Standard on some variants"],
  optional: ["□", "Optional extra"],
  not_listed: ["–", "No entry in this series' price list"],
  no_link: ["", "No curated price-list link"],
  not_covered: ["?", "Variant not in the equipment tables"],
};

export function Fitment({ tier, withLabel = false }: { tier?: string | null; withLabel?: boolean }) {
  if (!tier) return <span className="muted" title="No curated price-list link">·</span>;
  const [glyph, label] = TIER_TEXT[tier] ?? ["", tier];
  return (
    <span title={label} className="row" style={{ gap: 6, display: "inline-flex" }}>
      <span className="fit" aria-hidden>{glyph}</span>
      {withLabel ? <span className="small">{label}</span> : <span className="sr-only">{label}</span>}
    </span>
  );
}

export function tierLabel(tier?: string | null) {
  return tier ? TIER_TEXT[tier]?.[1] ?? tier : "No curated price-list link";
}

/** Complaint index with its 95% interval on a log scale around 1.0 ("as expected"). */
export function IndexGlyph({
  index,
  low,
  high,
  verdict,
  width = 140,
}: {
  index: number;
  low: number;
  high: number;
  verdict: string;
  width?: number;
}) {
  const lo = Math.log(0.25);
  const hi = Math.log(4);
  const x = (v: number) => {
    const c = Math.min(Math.max(Math.log(Math.max(v, 0.01)), lo), hi);
    return 4 + ((c - lo) / (hi - lo)) * (width - 8);
  };
  const color = VERDICT_COLORS[verdict] && verdict !== "Not enough data" ? VERDICT_COLORS[verdict] : "var(--muted-soft)";
  return (
    <svg width={width} height={18} role="img" aria-label={`Complaint index ${fmtNum(index)}, 95% interval ${fmtNum(low)} to ${fmtNum(high)}`}>
      <line x1={x(1)} x2={x(1)} y1={1} y2={17} stroke="var(--hairline-strong)" strokeWidth={1} />
      <line x1={x(low)} x2={x(high)} y1={9} y2={9} stroke="var(--muted)" strokeWidth={2} strokeLinecap="round" />
      <circle cx={x(index)} cy={9} r={5} fill={color} stroke="#fff" strokeWidth={2} />
      <title>{`Complaint index ${fmtNum(index)} (95% CI ${fmtNum(low)}–${fmtNum(high)}); 1.0 = as expected for the channels`}</title>
    </svg>
  );
}

/** A single-series 0–1 bar (score or weight share), blue on a blue track. */
export function Meter({ value, width = 120, label }: { value: number | null; width?: number; label: string }) {
  const v = value === null ? 0 : Math.max(0, Math.min(1, value));
  return (
    <svg width={width} height={10} role="img" aria-label={`${label}: ${value === null ? "missing" : fmtNum(value)}`}>
      <rect x={0} y={1} width={width} height={8} fill={value === null ? "var(--surface-soft)" : "var(--data-blue-track)"} />
      {value !== null && <rect x={0} y={1} width={Math.max(v * width, v > 0 ? 3 : 0)} height={8} fill="var(--data-blue)" />}
    </svg>
  );
}

export function Loading({ what }: { what: string }) {
  return (
    <div className="state" role="status">
      <p>Loading {what}…</p>
      <div className="skeleton" style={{ width: "60%" }} />
      <div className="skeleton" style={{ width: "40%" }} />
    </div>
  );
}

export function ErrorState({ message }: { message: string }) {
  return (
    <div className="state">
      <p className="error">Could not load data: {message}</p>
      <p className="small">Check that the API is running: python -m bmw_feedback serve</p>
    </div>
  );
}

