import type { Fitment } from "../types";
import { Fitment as FitGlyph, tierLabel } from "./marks";

/** How the same feature is offered across the three series in the DE price lists. */
export default function PriceLadder({ ladder }: { ladder: Fitment[] }) {
  if (!ladder.some((l) => l.tier !== "no_link")) {
    return (
      <p className="small muted">
        This feature has no curated link to the price lists, so availability and price are not shown.
      </p>
    );
  }
  return (
    <div className="specs">
      {ladder.map((l) => (
        <div key={l.model} className="spec">
          <p className="spec__label">
            {MODEL_NAMES[l.model ?? ""]} ({l.model})
          </p>
          <p className="spec__value">
            {l.tier === "optional" && l.price_min_eur ? fmtEur(l.price_min_eur) : shortTier(l.tier)}
          </p>
          <div className="row small" style={{ gap: 8 }}>
            <FitGlyph tier={l.tier} />
            <span>{tierLabel(l.tier)}</span>
          </div>
          {l.n_variants !== undefined && (
            <p className="caption">
              Standard on {l.n_standard} and optional on {l.n_optional} of {l.n_variants} variants in the equipment tables
              {l.price_pct_of_base ? `; ${fmtNum(l.price_pct_of_base, 1)}% of the lowest base price` : ""}
            </p>
          )}
          {l.items.length > 0 && (
            <p className="caption">
              {l.items
                .slice(0, 3)
                .map((i) => `${i.name}${i.sa_code ? ` (SA ${i.sa_code})` : ""}, p.${i.page}`)
                .join("; ")}
              {l.items.length > 3 ? `; and ${l.items.length - 3} more` : ""}
            </p>
          )}
        </div>
      ))}
    </div>
  );
}

function shortTier(tier: string) {
  return (
    {
      standard_all: "Standard",
      standard_some: "Partly standard",
      optional: "Optional",
      not_listed: "Not listed",
      no_link: "No link",
    } as Record<string, string>
  )[tier] ?? tier;
}

import { useState } from "react";
import { postJSON } from "../api";
import type { Decision, EvaluateResult, FeatureResult } from "../types";

const PM_KEY = "pds.pm-name";

function storedName() {
  try {
    return localStorage.getItem(PM_KEY) ?? "";
  } catch {
    return "";
  }
}

/** Accept or override the system's recommendation; stored with the policy and data hashes. */
export default function DecisionForm({ result, feature }: { result: EvaluateResult; feature: FeatureResult }) {
  const [pm, setPm] = useState(storedName);
  const [decision, setDecision] = useState<"accept" | "override">("accept");
  const [rationale, setRationale] = useState("");
  const [saved, setSaved] = useState<Decision | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setBusy(true);
    setError(null);
    try {
      try {
        localStorage.setItem(PM_KEY, pm);
      } catch {
        /* storage unavailable: the name is just not remembered */
      }
      const entry = await postJSON<Decision>("/api/decisions", {
        pm,
        idea: result.idea || feature.feature,
        feature: feature.feature,
        decision,
        rationale,
        system_recommendation: {
          headline: feature.headline,
          rollup_score: feature.rollup.score,
          cells: feature.cells.map((c) => ({ model: c.model, market: c.market, recommendation: c.recommendation, score: c.score })),
        },
        policy: result.policy,
        policy_hash: result.policy_hash,
        data_hash: result.data_hash,
      });
      setSaved(entry);
      setRationale("");
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setBusy(false);
    }
  }

  return (
    <form className="decision-form" onSubmit={submit} aria-labelledby={`decide-${feature.feature}`}>
      <h3 id={`decide-${feature.feature}`}>Record your decision on {feature.feature}</h3>
      <p className="small muted measure">
        The log keeps your decision next to the system's recommendation, the policy ({result.policy_hash}) and the data
        version ({result.data_hash}), so anyone can see where a PM followed or overrode the evidence and why.
      </p>
      <div className="decision-form__grid">
        <div className="field">
          <label htmlFor={`pm-${feature.feature}`}>Your name</label>
          <input id={`pm-${feature.feature}`} className="input" value={pm} onChange={(e) => setPm(e.target.value)} required />
        </div>
        <div className="field">
          <span className="label">Decision</span>
          <div className="row" style={{ gap: 12 }} role="radiogroup">
            {(["accept", "override"] as const).map((d) => (
              <button
                type="button"
                key={d}
                className="tile tile--compact"
                aria-pressed={decision === d}
                role="radio"
                aria-checked={decision === d}
                onClick={() => setDecision(d)}
              >
                <span className="tile__title">{d === "accept" ? "Follow the recommendation" : "Override it"}</span>
              </button>
            ))}
          </div>
        </div>
      </div>
      <div className="field">
        <label htmlFor={`why-${feature.feature}`}>Rationale</label>
        <textarea
          id={`why-${feature.feature}`}
          className="textarea"
          value={rationale}
          onChange={(e) => setRationale(e.target.value)}
          placeholder={decision === "override" ? "What do you know that the data does not show?" : "Why does this recommendation hold?"}
          required
          minLength={3}
        />
      </div>
      <div className="row">
        <button className="btn" type="submit" disabled={busy || !pm.trim() || rationale.trim().length < 3}>
          {busy ? "Recording…" : "Record decision"}
        </button>
        {saved && (
          <p className="small" role="status">
            Decision recorded as {saved.id} at {new Date(saved.recorded_at).toLocaleString("en-GB")}.
          </p>
        )}
        {error && <p className="small error">Not recorded: {error}</p>}
      </div>
    </form>
  );
}

import { useEffect, useRef, useState } from "react";
import { Link } from "react-router-dom";
import { MODEL_NAMES, fmtInt, fmtNum, postJSON, useApi } from "../api";
import type { EvaluateResult, FeatureResult, Overview, Policy } from "../types";
import DecisionMatrix from "../components/DecisionMatrix";
import EvidencePanel from "../components/EvidencePanel";
import PolicyPanel from "../components/PolicyPanel";
import PriceLadder from "../components/PriceLadder";
import DecisionForm from "../components/DecisionForm";
import { ErrorState, IndexGlyph, Verdict } from "../components/marks";

// Example questions a PM might ask; the last one has no direct evidence in the data on purpose.
const EXAMPLES = ["Head-up display", "Seat massage", "Climate control", "Automatic doors", "Wireless charging", "Vacuum for pet hair"];

export default function Evaluate({ overview }: { overview: Overview | null }) {
  const { data: policyData, error: policyError } = useApi<{ default: Policy }>("/api/policy");
  const [idea, setIdea] = useState("");
  const [result, setResult] = useState<EvaluateResult | null>(null);
  const [selected, setSelected] = useState<string[]>([]);
  const [policy, setPolicy] = useState<Policy | null>(null);
  const [showPolicy, setShowPolicy] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const resultsRef = useRef<HTMLDivElement>(null);
  const firstPolicy = useRef(true);

  useEffect(() => {
    if (policyData && !policy) setPolicy(policyData.default);
  }, [policyData, policy]);

  async function run(nextIdea: string, features?: string[], pol: Policy | null = policy, scroll = true) {
    if (!nextIdea.trim() && !features?.length) return;
    setBusy(true);
    setError(null);
    try {
      const r = await postJSON<EvaluateResult>("/api/evaluate", {
        idea: nextIdea,
        features: features && features.length ? features : undefined,
        policy: pol ?? undefined,
      });
      setResult((prev) => (features && prev?.resolution && !r.resolution ? { ...r, resolution: prev.resolution } : r));
      setSelected(r.features.map((f) => f.feature));
      if (scroll) requestAnimationFrame(() => resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }));
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setBusy(false);
    }
  }

  // Re-evaluate the same features when the PM changes the policy
  useEffect(() => {
    if (firstPolicy.current) {
      firstPolicy.current = false;
      return;
    }
    if (!result || !policy || !selected.length) return;
    const t = setTimeout(() => run(result.idea, selected, policy, false), 350);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [policy]);

  const toggle = (f: string) => setSelected((s) => (s.includes(f) ? s.filter((x) => x !== f) : [...s, f]));

  return (
    <>
      <section className="band band--dark hero">
        <div className="wrap">
          <h1 className="hero__title">Should we build it, and for which market?</h1>
          <p className="lead hero__lead">
            Describe a feature or a customer problem. The answer is assembled from{" "}
            {overview ? `${fmtInt(overview.comments)} customer comments` : "customer comments"}, the 2025 customer studies,
            sales volumes and the July 2026 price lists of the 1, 5 and 7 Series. Every number links back to its source.
          </p>
          <form
            className="hero__form"
            onSubmit={(e) => {
              e.preventDefault();
              run(idea);
            }}
          >
            <label htmlFor="idea" className="sr-only">
              Feature idea or customer problem
            </label>
            <input
              id="idea"
              className="input hero__input"
              value={idea}
              onChange={(e) => setIdea(e.target.value)}
              placeholder="For example: a head-up display that works with polarised sunglasses"
              autoComplete="off"
            />
            <button className="btn hero__btn" type="submit" disabled={busy || !idea.trim()}>
              {busy ? "Evaluating…" : "Evaluate"}
            </button>
          </form>
          <div className="chips hero__examples" aria-label="Example questions">
            {EXAMPLES.map((ex) => (
              <button
                key={ex}
                className="chip"
                onClick={() => {
                  setIdea(ex);
                  run(ex);
                }}
              >
                {ex}
              </button>
            ))}
          </div>
          {error && <p className="error hero__error">The evaluation failed: {error}</p>}
          {policyError && <ErrorState message={policyError} />}
        </div>
      </section>

      <div ref={resultsRef} />
      {result && (
        <section className="band">
          <div className="wrap stack-lg">
            {result.resolution && (
              <MatchSection
                result={result}
                selected={selected}
                toggle={toggle}
                busy={busy}
                onEvaluate={() => run(result.idea, selected)}
              />
            )}

            {policy && policyData && (
              <div className="stack">
                <div className="row">
                  <button className="btn btn--secondary btn--small" onClick={() => setShowPolicy((s) => !s)} aria-expanded={showPolicy}>
                    {showPolicy ? "Hide decision policy" : "Adjust decision policy"}
                  </button>
                  <span className="small muted">
                    Weights: complaints {fmtNum(policy.weights.complaints)}, breadth {fmtNum(policy.weights.breadth)}, requests{" "}
                    {fmtNum(policy.weights.requests)}, survey {fmtNum(policy.weights.survey)}. Policy {result.policy_hash}.
                  </span>
                </div>
                {showPolicy && (
                  <PolicyPanel
                    policy={policy}
                    defaults={policyData.default}
                    hash={result.policy_hash}
                    onChange={setPolicy}
                    onReset={() => setPolicy(policyData.default)}
                  />
                )}
              </div>
            )}

            {result.features.map((f) => (
              <FeatureBlock key={f.feature} f={f} result={result} />
            ))}
          </div>
        </section>
      )}
    </>
  );
}

function MatchSection({
  result,
  selected,
  toggle,
  busy,
  onEvaluate,
}: {
  result: EvaluateResult;
  selected: string[];
  toggle: (f: string) => void;
  busy: boolean;
  onEvaluate: () => void;
}) {
  const res = result.resolution!;
  const evaluated = result.features.map((f) => f.feature).sort().join("|");
  const dirty = [...selected].sort().join("|") !== evaluated;
  return (
    <div className="stack">
      <h2>What “{res.idea}” matches in the feedback</h2>
      {res.status === "none" || result.status === "no_direct_evidence" ? (
        <p className="note note--warn">
          No feature in the customer feedback matches this idea directly (best match score{" "}
          {fmtNum(res.matches[0]?.score ?? 0)}). Treat it as a new idea without customer evidence in this data, or select
          a related feature below to see the nearest evidence.
        </p>
      ) : (
        <p className="small muted measure">
          Matched by feature name, alias or the text classifier trained on the labelled comments. Select the features to
          evaluate.
        </p>
      )}
      <div className="tiles">
        {res.matches.map((m) => (
          <button key={m.feature} className="tile" aria-pressed={selected.includes(m.feature)} onClick={() => toggle(m.feature)}>
            <span className="tile__title">{m.feature}</span>
            <span className="caption">{m.domain}</span>
            <span className="row small" style={{ gap: 12 }}>
              <Verdict verdict={m.verdict} />
              <span className="muted num">{fmtInt(m.n_comments)} comments</span>
            </span>
            <span className="caption">
              {m.how}, match {fmtNum(m.score)}
              {m.umbrella ? ". Umbrella label: general praise is filed here" : ""}
            </span>
          </button>
        ))}
      </div>
      <div className="row">
        <button className="btn" onClick={onEvaluate} disabled={busy || !selected.length || !dirty}>
          {busy ? "Evaluating…" : `Evaluate ${selected.length} selected`}
        </button>
        {!dirty && selected.length > 0 && <span className="small muted">Showing the selected features below.</span>}
      </div>
    </div>
  );
}

function FeatureBlock({ f, result }: { f: FeatureResult; result: EvaluateResult }) {
  const firstSold = f.cells.find((c) => c.recommendation !== "Not sold" && c.recommendation !== "Insufficient evidence") ?? f.cells[0];
  const [sel, setSel] = useState<string>(`${firstSold.model}|${firstSold.market}`);
  const cell = f.cells.find((c) => `${c.model}|${c.market}` === sel) ?? firstSold;
  const fit = f.price_ladder.find((l) => l.model === cell.model);
  return (
    <article className="feature-block stack-lg" aria-labelledby={`fb-${f.feature}`}>
      <header className="stack">
        <div className="spread">
          <h2 id={`fb-${f.feature}`}>{f.feature}</h2>
          <Link className="textlink" to={`/features/${encodeURIComponent(f.feature)}`}>
            Full feature verdict
          </Link>
        </div>
        <div className="row small">
          <span className="muted">{f.domain}</span>
          <Verdict verdict={f.overall.verdict} />
          <span className="num">
            {fmtInt(f.overall.n_comments)} comments, complaint index {fmtNum(f.overall.complaint_index)}
          </span>
          {f.umbrella && <span className="muted">Umbrella label: judge at domain level</span>}
        </div>
        <p className="lead">{f.headline}</p>
      </header>

      <div className="decision-grid">
        <DecisionMatrix cells={f.cells} models={result.models} markets={result.markets} selected={sel} onSelect={setSel} />
        <EvidencePanel cell={cell} fitment={fit} />
      </div>

      <div className="stack">
        <h3>How the series are equipped today</h3>
        <p className="small muted measure">
          German price lists, July 2026, EUR incl. 19% VAT. Prices for other markets are not in the data.
        </p>
        <PriceLadder ladder={f.price_ladder} />
      </div>

      {f.specs.length > 0 && (
        <details>
          <summary>Technical data linked to {f.feature} ({f.specs.length} values)</summary>
          <div className="table-scroll" style={{ marginTop: 12 }}>
            <table className="table">
              <thead>
                <tr>
                  <th>Model</th>
                  <th>Variant</th>
                  <th>Attribute (as printed)</th>
                  <th>Value</th>
                  <th>Page</th>
                </tr>
              </thead>
              <tbody>
                {f.specs.map((s, i) => (
                  <tr key={i}>
                    <td>{MODEL_NAMES[s.model]}</td>
                    <td>{s.variant}</td>
                    <td>{s.attribute}</td>
                    <td className="num">{s.value}</td>
                    <td className="caption">
                      {s.model} p.{s.page}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </details>
      )}

      <IndexNote f={f} />
      <DecisionForm result={result} feature={f} />
    </article>
  );
}

function IndexNote({ f }: { f: FeatureResult }) {
  return (
    <div className="row small muted">
      <IndexGlyph index={f.overall.complaint_index} low={f.overall.complaint_index} high={f.overall.complaint_index} verdict={f.overall.verdict} />
      <span>
        Complaint index 1.0 means as many complaints as expected for the channels the feature is discussed in; above 1.0
        means more.
      </span>
    </div>
  );
}

