import { useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { MODEL_NAMES, fmtInt, fmtNum, useApi } from "../api";
import type { FeatureRow } from "../types";
import { ErrorState, Fitment, IndexGlyph, Loading, Verdict } from "../components/marks";

const VERDICTS = ["Bad", "Leaning bad", "Mixed", "Leaning good", "Good", "Not enough data"];
type SortKey = "feature" | "n_comments" | "complaint_index" | "request_index";

export default function Features() {
  const { data, error, loading } = useApi<FeatureRow[]>("/api/features");
  const navigate = useNavigate();
  const [q, setQ] = useState("");
  const [verdicts, setVerdicts] = useState<string[]>([]);
  const [domain, setDomain] = useState("");
  const [specificOnly, setSpecificOnly] = useState(true);
  const [sort, setSort] = useState<{ key: SortKey; dir: 1 | -1 }>({ key: "complaint_index", dir: -1 });

  const domains = useMemo(() => [...new Set((data ?? []).map((d) => d.domain))].sort(), [data]);
  const rows = useMemo(() => {
    let r = (data ?? []).filter(
      (d) =>
        (!q || d.feature.toLowerCase().includes(q.toLowerCase())) &&
        (!verdicts.length || verdicts.includes(d.verdict)) &&
        (!domain || d.domain === domain) &&
        (!specificOnly || !d.umbrella),
    );
    r = [...r].sort((a, b) => {
      const va = a[sort.key];
      const vb = b[sort.key];
      return (typeof va === "string" ? va.localeCompare(vb as string) : (va as number) - (vb as number)) * sort.dir;
    });
    return r;
  }, [data, q, verdicts, domain, specificOnly, sort]);

  const header = (key: SortKey, label: string, right = false) => (
    <th className={right ? "r" : undefined} aria-sort={sort.key === key ? (sort.dir === 1 ? "ascending" : "descending") : "none"}>
      <button onClick={() => setSort((s) => ({ key, dir: s.key === key ? ((-s.dir) as 1 | -1) : -1 }))}>
        {label}
        {sort.key === key ? (sort.dir === 1 ? " ▲" : " ▼") : ""}
      </button>
    </th>
  );

  return (
    <section className="band">
      <div className="wrap stack-lg">
        <div className="stack">
          <h1>Feature verdicts</h1>
          <p className="lead">
            Every feature customers talk about, rated against what its feedback channels predict. A complaint index of 1.0
            means as many complaints as expected; the bar shows the 95% interval.
          </p>
        </div>

        <div className="filters">
          <div className="field" style={{ minWidth: 240, flex: 1 }}>
            <label htmlFor="fq">Search features</label>
            <input id="fq" className="input" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Head-up display, seats, charging…" />
          </div>
          <div className="field" style={{ minWidth: 240 }}>
            <label htmlFor="fd">Domain</label>
            <select id="fd" className="select" value={domain} onChange={(e) => setDomain(e.target.value)}>
              <option value="">All domains</option>
              {domains.map((d) => (
                <option key={d}>{d}</option>
              ))}
            </select>
          </div>
          <label className="check" style={{ alignSelf: "end", paddingBottom: 14 }}>
            <input type="checkbox" checked={specificOnly} onChange={(e) => setSpecificOnly(e.target.checked)} />
            Hide umbrella labels
          </label>
        </div>
        <div className="chips" aria-label="Filter by verdict">
          {VERDICTS.map((v) => (
            <button
              key={v}
              className="chip"
              aria-pressed={verdicts.includes(v)}
              onClick={() => setVerdicts((s) => (s.includes(v) ? s.filter((x) => x !== v) : [...s, v]))}
            >
              {v}
            </button>
          ))}
        </div>

        {loading && <Loading what="feature verdicts" />}
        {error && <ErrorState message={error} />}
        {data && (
          <>
            <p className="small muted">
              {rows.length} of {data.length} features. Price-list columns use the PDFs' marks: ■ standard, □ optional, – no
              entry for that series, · no curated link.
            </p>
            <div className="table-scroll">
              <table className="table">
                <thead>
                  <tr>
                    {header("feature", "Feature")}
                    <th>Verdict</th>
                    {header("complaint_index", "Complaint index (95% CI)")}
                    {header("n_comments", "Comments", true)}
                    {header("request_index", "Request index", true)}
                    {Object.keys(MODEL_NAMES).map((m) => (
                      <th key={m} className="r" title={`${MODEL_NAMES[m]} price list`}>
                        {m}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r) => (
                    <tr key={r.feature} className="clickable" onClick={() => navigate(`/features/${encodeURIComponent(r.feature)}`)}>
                      <td>
                        <a href={`/features/${encodeURIComponent(r.feature)}`} onClick={(e) => e.preventDefault()} style={{ textDecoration: "none" }}>
                          <strong>{r.feature}</strong>
                        </a>
                        <div className="caption">{r.domain}</div>
                      </td>
                      <td>
                        <Verdict verdict={r.verdict} />
                        {r.requested && <div className="caption">Also an unmet need</div>}
                      </td>
                      <td>
                        <div className="row" style={{ gap: 8, flexWrap: "nowrap" }}>
                          <IndexGlyph index={r.complaint_index} low={r.ci_low} high={r.ci_high} verdict={r.verdict} width={120} />
                          <span className="num small">{fmtNum(r.complaint_index)}</span>
                        </div>
                      </td>
                      <td className="r num">{fmtInt(r.n_comments)}</td>
                      <td className="r num">{fmtNum(r.request_index)}</td>
                      {Object.keys(MODEL_NAMES).map((m) => (
                        <td key={m} className="r">
                          <Fitment tier={r.fitment[m]} />
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}
      </div>
    </section>
  );
}

import { Link, useParams } from "react-router-dom";
import { MARKET_NAMES, MODEL_NAMES, fmtInt, fmtNum, fmtPct, useApi } from "../api";
import type { Fitment } from "../types";
import { ErrorState, IndexGlyph, Loading, Verdict } from "../components/marks";
import PriceLadder from "../components/PriceLadder";

interface Ci { index: number; ci_low: number; ci_high: number; observed: number; expected: number }
interface Card {
  feature: string;
  domain: string;
  verdict: string;
  confidence: string;
  n_comments: number;
  is_umbrella_label: boolean;
  requested: boolean;
  bad_kind: string;
  complaint_index: Ci;
  praise_index: Ci;
  request_index: Ci;
  adjusted_mix: Record<string, number>;
  raw_mix: Record<string, number>;
  domain_verdict: string;
  domain_complaint_index: number;
  reasons: Record<string, { families: Record<string, number>; reasons: Record<string, number> }>;
  quotes: Record<string, { comment_id: number; model: string; source: string; reason: string; text: string }[]>;
  by_model: { group: string; n_comments: number; complaint_index: number; verdict: string }[];
  by_engine: { group: string; n_comments: number; complaint_index: number; verdict: string }[];
  survey: { attribute: string; model: string; top2_box: number; bottom3_box: number }[];
  specs: { model: string; variant: string; attribute: string; value: string; page: number }[];
