}

const SENT = { positive: "Why customers like it", negative: "Why customers complain", request: "What customers ask for" } as const;

export default function FeatureDetail() {
  const { name = "" } = useParams();
  const { data: c, error, loading } = useApi<Card>(`/api/features/${encodeURIComponent(name)}`);
  return (
    <section className="band">
      <div className="wrap stack-lg">
        <Link className="textlink" to="/features">
          All feature verdicts
        </Link>
