          <>
            <header className="stack">
              <p className="small muted">{c.domain}</p>
              <h1>{c.feature}</h1>
              <div className="row">
                <Verdict verdict={c.verdict} />
                <span className="small muted">
                  {c.confidence} confidence, {fmtInt(c.n_comments)} comments
                </span>
                <IndexGlyph index={c.complaint_index.index} low={c.complaint_index.ci_low} high={c.complaint_index.ci_high} verdict={c.verdict} />
              </div>
              <p className="lead">{c.summary}</p>
            </header>

            <div className="specs">
              <Stat label="Complaint index (95% CI)" value={fmtNum(c.complaint_index.index)} note={`${fmtNum(c.complaint_index.ci_low)}–${fmtNum(c.complaint_index.ci_high)}; ${c.complaint_index.observed} observed vs ${fmtNum(c.complaint_index.expected, 1)} expected`} />
              <Stat label="Praise index" value={fmtNum(c.praise_index.index)} note={`${c.praise_index.observed} observed vs ${fmtNum(c.praise_index.expected, 1)} expected`} />
              <Stat label="Request index" value={fmtNum(c.request_index.index)} note={c.requested ? "A significant unmet need" : `${c.request_index.observed} observed vs ${fmtNum(c.request_index.expected, 1)} expected`} />
              <Stat label="Channel-adjusted mix" value={`${fmtPct(c.adjusted_mix.negative)} complaints`} note={`${fmtPct(c.adjusted_mix.positive)} praise, ${fmtPct(c.adjusted_mix.request)} requests (raw ${fmtPct(c.raw_mix.negative)} / ${fmtPct(c.raw_mix.positive)} / ${fmtPct(c.raw_mix.request)})`} />
            </div>

            <div className="two-col">
              {(Object.keys(SENT) as (keyof typeof SENT)[]).map((s) => (
                <div key={s} className="stack">
                  <h3>{SENT[s]}</h3>
                  {Object.keys(c.reasons[s].families).length === 0 ? (
                    <p className="small muted">No comments of this kind.</p>
                  ) : (
                    <ul className="reasons">
                      {Object.entries(c.reasons[s].families).map(([k, v]) => (
                        <li key={k}>
                          {k} <span className="muted num">({v})</span>
                        </li>
                      ))}
                    </ul>
                  )}
                  {c.quotes[s].map((q) => (
                    <blockquote key={q.comment_id} className="quote">
                      <p>“{q.text}”</p>
                      <p className="caption">
                        Comment {q.comment_id}, {MODEL_NAMES[q.model] ?? q.model}, {q.source}. Reason: {q.reason}
                      </p>
                    </blockquote>
                  ))}
                </div>
              ))}
            </div>

            <div className="stack">
              <h2>By series and market</h2>
              <div className="table-scroll">
                <table className="table">
                  <thead>
                    <tr>
                      <th>Series</th>
                      <th>Market</th>
                      <th className="r">Comments</th>
                      <th className="r">Complaint index</th>
                      <th>Verdict</th>
                    </tr>
                  </thead>
                  <tbody>
                    {c.by_model_market.map((r) => (
                      <tr key={`${r.model}${r.market}`}>
                        <td>
                          {MODEL_NAMES[r.model]} ({r.model})
                        </td>
                        <td>{MARKET_NAMES[r.market] ?? r.market}</td>
                        <td className="r num">{fmtInt(r.n_comments)}</td>
                        <td className="r num">{fmtNum(r.complaint_index)}</td>
                        <td>
                          <Verdict verdict={r.verdict} />
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <p className="small muted">
                By powertrain:{" "}
                {c.by_engine.map((b) => `${b.group} ${b.verdict.toLowerCase()} (index ${fmtNum(b.complaint_index)}, ${b.n_comments} comments)`).join("; ")}.
                The data has no customer comments from China.
              </p>
            </div>

            {c.survey.length > 0 && (
              <div className="stack">
                <h2>US customer study 2025</h2>
                <div className="table-scroll">
                  <table className="table">
                    <thead>
                      <tr>
                        <th>Attribute</th>
                        <th>Series</th>
                        <th className="r">Top-2 box (Delightful, I love it)</th>
                        <th className="r">Bottom-3 box</th>
                      </tr>
                    </thead>
                    <tbody>
                      {c.survey.map((s, i) => (
                        <tr key={i}>
                          <td>{s.attribute}</td>
                          <td>{MODEL_NAMES[s.model] ?? s.model}</td>
                          <td className="r num">{fmtPct(s.top2_box)}</td>
