            <div className="stack">
              <h2>Price lists</h2>
              <p className="small muted">German price lists, July 2026, EUR incl. 19% VAT.</p>
              <PriceLadder ladder={c.price_ladder} />
            </div>

            {c.specs.length > 0 && (
              <div className="stack">
                <h2>Technical data</h2>
                <div className="table-scroll">
                  <table className="table">
                    <thead>
                      <tr>
                        <th>Series</th>
                        <th>Variant</th>
                        <th>Attribute (as printed)</th>
                        <th>Value</th>
                        <th>Source</th>
                      </tr>
                    </thead>
                    <tbody>
                      {c.specs.map((s, i) => (
                        <tr key={i}>
                          <td>{MODEL_NAMES[s.model]}</td>
                          <td>{s.variant}</td>
                          <td>{s.attribute}</td>
                          <td className="num">{s.value}</td>
                          <td className="caption">
                            {s.model}_OptionList.PDF p.{s.page}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            <Link className="btn" to="/" state={{ idea: c.feature }}>
              Evaluate {c.feature} by market
            </Link>
          </>
        )}
      </div>
    </section>
  );
}

function Stat({ label, value, note }: { label: string; value: string; note: string }) {
  return (
    <div className="spec">
      <p className="spec__label">{label}</p>
      <p className="spec__value num">{value}</p>
      <p className="caption">{note}</p>
    </div>
  );
}

import { useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { MODEL_NAMES, fmtEur, fmtInt, useApi } from "../api";
import { ErrorState, Loading } from "../components/marks";

interface Variant {
  variant: string;
  powertrain: string;
  engine: string;
  page: number;
  transmission: string;
  power_kw: number;
  power_ps: number;
  base_price_eur: number;
  base_price_net_eur: number;
  in_equipment_tables: boolean;
}
interface CatalogModel {
  model: string;
  name: string;
  file: string;
  variants: Variant[];
  pages: { page: number; page_type: string; glyphs: number; cells: number; items: number }[];
  items: number;
}
interface Catalog {
  models: CatalogModel[];
  validation: {
    table_pages: number;
    glyphs_assigned: number;
    option_price_pairs_checked: number;
    base_prices_checked: number;
    power_cross_checked: number;
    source_price_anomalies: { model: string; page: number; item_id: string; gross: number; net: number; net_x_1_19: number }[];
  };
}
interface ItemCell { status: "standard" | "optional"; price_eur: number | null; price_condition: string | null }
interface Item {
  item_id: string;
  page: number;
  page_type: string;
  section: string | null;
  name: string;
  sa_code: string | null;
  description: string | null;
  contents: string | null;
  conditions: string | null;
  cells: Record<string, ItemCell>;
  linked_features: string[];
}
interface Technical {
  variants: string[];
  rows: { block: string; group: string | null; attribute: string; page: number; values: Record<string, string> }[];
}

const PAGE_TYPES: [string, string][] = [
  ["standard_equipment", "Standard equipment"],
  ["optional_equipment", "Optional equipment"],
  ["wheels", "Wheels"],
  ["paint", "Paint"],
  ["interior_colour", "Upholstery and trims"],
  ["technical", "Technical data"],
];

export default function PriceLists() {
  const { data, error, loading } = useApi<Catalog>("/api/catalog");
  const [model, setModel] = useState("G60");
  const [pageType, setPageType] = useState("optional_equipment");
  const [q, setQ] = useState("");
  const isTech = pageType === "technical";
  const items = useApi<{ variants: string[]; items: Item[] }>(isTech ? null : `/api/catalog/${model}/items?page_type=${pageType}`);
  const tech = useApi<Technical>(isTech ? `/api/catalog/${model}/technical` : null);
  const m = data?.models.find((x) => x.model === model);

  const filtered = useMemo(() => {
    const list = items.data?.items ?? [];
    if (!q) return list;
    const ql = q.toLowerCase();
    return list.filter((i) => `${i.name} ${i.contents ?? ""} ${i.sa_code ?? ""} ${i.linked_features.join(" ")}`.toLowerCase().includes(ql));
  }, [items.data, q]);

  return (
    <>
      <section className="band band--soft band--tight">
        <div className="wrap stack">
          <h1>Price lists</h1>
          <p className="lead">
            The three German price lists (July 2026), parsed cell by cell: which variant has an item as standard (■) or as
            an option (□), at what price, and the technical data per variant.
          </p>
          {data && (
            <p className="small">
              Checks passed on every build: {fmtInt(data.validation.glyphs_assigned)} of {fmtInt(data.validation.glyphs_assigned)} ■/□ marks
              on {data.validation.table_pages} table pages assigned to a variant column; {fmtInt(data.validation.option_price_pairs_checked)} option
              prices and {data.validation.base_prices_checked} base prices satisfy gross = net × 1.19; power on the price pages matches the
              technical data for all {data.validation.power_cross_checked} variants.
              {data.validation.source_price_anomalies.map((a) => (
                <span key={a.item_id}>
                  {" "}
                  One printed anomaly is kept as printed: {a.model} p.{a.page} shows EUR {fmtInt(a.gross)} gross with {a.net.toFixed(2)} net
                  (net × 1.19 = {a.net_x_1_19.toFixed(2)}).
                </span>
              ))}
            </p>
          )}
        </div>
      </section>

      <section className="band band--tight">
        <div className="wrap stack-lg">
          {loading && <Loading what="price lists" />}
          {error && <ErrorState message={error} />}
          {data && (
            <>
              <div className="tabs" role="tablist" aria-label="Series">
                {data.models.map((x) => (
                  <button key={x.model} role="tab" className="tab" aria-selected={x.model === model} onClick={() => setModel(x.model)}>
                    {x.name} ({x.model})
                  </button>
                ))}
              </div>

              {m && (
                <div className="stack">
                  <div className="spread">
                    <h2>
                      {MODEL_NAMES[m.model]} variants
                    </h2>
                    <span className="caption">{m.file}</span>
                  </div>
                  <div className="variant-grid">
                    {m.variants.map((v) => (
                      <div key={v.variant} className="variant">
                        <p className="tile__title">{v.variant}</p>
                        <p className="spec__value num">{fmtEur(v.base_price_eur)}</p>
                        <p className="caption">
                          {v.powertrain} ({v.engine}), {v.power_kw} kW ({v.power_ps} PS)
                        </p>
                        <p className="caption">{v.transmission}</p>
                        <p className="caption">
                          Base price p.{v.page}
                          {v.in_equipment_tables ? "" : "; not in the equipment tables"}
                        </p>
                      </div>
                    ))}
                  </div>
                  {m.variants.some((v) => !v.in_equipment_tables) && (
                    <p className="note">
                      The equipment tables of this price list cover {m.variants.filter((v) => v.in_equipment_tables).length} of{" "}
                      {m.variants.length} variants; fitment for the others is unknown and is never filled in.
                    </p>
                  )}
                </div>
              )}

              <div className="stack">
                <div className="tabs" role="tablist" aria-label="Price-list section">
                  {PAGE_TYPES.map(([k, label]) => (
                    <button key={k} role="tab" className="tab" aria-selected={pageType === k} onClick={() => setPageType(k)}>
                      {label}
                    </button>
                  ))}
                </div>

                {!isTech && (
                  <div className="field" style={{ maxWidth: 420 }}>
                    <label htmlFor="iq">Filter items</label>
                    <input id="iq" className="input" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Name, SA code or linked feature" />
                  </div>
                )}

                {!isTech && items.loading && <Loading what="items" />}
                {!isTech && items.error && <ErrorState message={items.error} />}
                {!isTech && items.data && (
                  <div className="table-scroll">
                    <table className="table equip">
                      <thead>
                        <tr>
                          <th>Item</th>
                          <th>SA</th>
                          {items.data.variants.map((v) => (
                            <th key={v} className="equip__var">
                              <span>{v}</span>
                            </th>
                          ))}
                          <th>Linked feedback features</th>
                        </tr>
                      </thead>
                      <tbody>
                        {filtered.map((it) => (
                          <tr key={it.item_id}>
                            <td style={{ minWidth: 260 }}>
                              <strong>{it.name}</strong>
                              {it.section && <div className="caption">{it.section}</div>}
                              {it.contents && (
                                <details>
                                  <summary className="caption">Contents</summary>
                                  <ul className="items">
                                    {it.contents.split(" | ").map((c, i) => (
                                      <li key={i} className="caption">
                                        {c}
                                      </li>
                                    ))}
                                  </ul>
                                </details>
                              )}
                              {it.conditions && <div className="caption">{it.conditions}</div>}
                              <div className="caption">p.{it.page}</div>
                            </td>
                            <td className="num small">{it.sa_code ?? "–"}</td>
                            {items.data!.variants.map((v) => {
                              const c = it.cells[v];
                              return (
                                <td key={v} className="equip__cell" title={c?.price_condition ?? undefined}>
                                  {c ? (
                                    <>
                                      <span className="fit" aria-label={c.status}>
                                        {c.status === "standard" ? "■" : "□"}
                                      </span>
                                      {c.status === "optional" && c.price_eur !== null && (
                                        <div className="caption num">{c.price_eur === 0 ? "no charge" : fmtInt(c.price_eur)}</div>
                                      )}
                                    </>
                                  ) : (
                                    <span className="muted" aria-label="not available">
                                      &nbsp;
                                    </span>
                                  )}
                                </td>
                              );
                            })}
                            <td className="small">
                              {it.linked_features.length
                                ? it.linked_features.map((f, i) => (
                                    <span key={f}>
                                      {i > 0 && ", "}
                                      <Link to={`/features/${encodeURIComponent(f)}`}>{f}</Link>
                                    </span>
                                  ))
                                : "–"}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    <p className="caption" style={{ marginTop: 8 }}>
                      ■ standard, □ optional (EUR incl. 19% VAT, lowest listed price for that variant; hover for the
                      condition attached to a price), empty: not offered on that variant.
                    </p>
                  </div>
                )}

                {isTech && tech.loading && <Loading what="technical data" />}
                {isTech && tech.error && <ErrorState message={tech.error} />}
                {isTech && tech.data && <TechTable t={tech.data} />}
              </div>
            </>
          )}
        </div>
      </section>
    </>
  );
}

function TechTable({ t }: { t: Technical }) {
  let lastGroup: string | null = null;
  let lastBlock: string | null = null;
  return (
    <div className="table-scroll">
      <table className="table">
        <thead>
          <tr>
            <th>Attribute (as printed)</th>
            {t.variants.map((v) => (
              <th key={v} className="r">
                {v}
              </th>
            ))}
            <th>Page</th>
          </tr>
        </thead>
        <tbody>
          {t.rows.map((r, i) => {
            const newBlock = r.block !== lastBlock;
            const newGroup = r.group !== lastGroup || newBlock;
            lastBlock = r.block;
            lastGroup = r.group;
            return (
              <>
                {newGroup && (
                  <tr key={`g${i}`} className="group-row">
                    <td colSpan={t.variants.length + 2}>
                      <strong>{r.group ?? r.block}</strong>
                      {newBlock && r.group && <span className="caption"> {r.block}</span>}
                    </td>
                  </tr>
                )}
                <tr key={i}>
                  <td>{r.attribute}</td>
                  {t.variants.map((v) => (
                    <td key={v} className="r num">
                      {r.values[v] ?? ""}
                    </td>
                  ))}
                  <td className="caption">p.{r.page}</td>
                </tr>
              </>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

import { MARKET_NAMES, MODEL_NAMES, compact, fmtInt, fmtPct, useApi } from "../api";
import { ErrorState, Loading } from "../components/marks";

interface MarketsData {
  sales: { model_group: string; market: string; year: number; volume: number }[];
  feedback: { model: string; market: string; comments: number }[];
  representativeness: { model: string; market: string; comments: number; feedback_share: number; sales_share: number; weight: number }[];
  survey: { sheet: string; market: string; model: string; attributes: number }[];
}

const GROUP_LABEL: Record<string, string> = { F70: "1 Series (F70)", G60_G68: "5 Series (G60 and G68 long wheelbase)", G70: "7 Series (G70)" };
const GROUP_MODEL: Record<string, string> = { F70: "F70", G60_G68: "G60", G70: "G70" };
const MARKETS = ["EU", "US", "CN", "RoW"];
const YEARS = [2024, 2025, 2030];

export default function Markets() {
  const { data, error, loading } = useApi<MarketsData>("/api/markets");
  return (
    <>
      <section className="band band--soft band--tight">
        <div className="wrap stack">
          <h1>Markets</h1>
          <p className="lead">
            Where each series sells, and how well the customer feedback represents those markets. A recommendation is only
            as strong as the evidence from the market it is for.
          </p>
        </div>
      </section>
      <section className="band band--tight">
        <div className="wrap stack-lg">
          {loading && <Loading what="market data" />}
          {error && <ErrorState message={error} />}
          {data && (
            <>
              <SalesTable data={data} />
              <Coverage data={data} />
              <Survey data={data} />
            </>
          )}
        </div>
      </section>
    </>
  );
}

function SalesTable({ data }: { data: MarketsData }) {
  const max = Math.max(...data.sales.map((s) => s.volume));
  const get = (g: string, m: string, y: number) => data.sales.find((s) => s.model_group === g && s.market === m && s.year === y)?.volume ?? 0;
  return (
    <div className="stack">
      <h2>Sales volume by market</h2>
      <p className="small muted">sales_volumes.xlsx. 2030 is a forecast. Bars show 2025 on one scale for all series.</p>
      <div className="table-scroll">
        <table className="table">
          <thead>
            <tr>
              <th>Series</th>
              <th>Market</th>
              {YEARS.map((y) => (
                <th key={y} className="r">
                  {y === 2030 ? "2030 forecast" : y}
                </th>
              ))}
              <th>2025</th>
            </tr>
          </thead>
          <tbody>
            {Object.keys(GROUP_LABEL).flatMap((g) =>
              MARKETS.map((m, i) => {
                const v25 = get(g, m, 2025);
                return (
                  <tr key={g + m}>
                    <td>{i === 0 ? <strong>{GROUP_LABEL[g]}</strong> : ""}</td>
                    <td>{MARKET_NAMES[m]}</td>
                    {YEARS.map((y) => (
                      <td key={y} className="r num">
                        {get(g, m, y) === 0 ? <span className="muted">not sold</span> : fmtInt(get(g, m, y))}
                      </td>
                    ))}
                    <td style={{ width: 260 }}>
                      <svg width={240} height={14} role="img" aria-label={`2025 volume ${fmtInt(v25)}`}>
                        <rect x={0} y={3} width={(v25 / max) * 200} height={8} fill="var(--data-blue)" />
                        <text x={(v25 / max) * 200 + 6} y={11} fontSize={11} fill="var(--muted)">
                          {v25 ? compact(v25) : ""}
                        </text>
                      </svg>
                    </td>
                  </tr>
                );
              }),
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function Coverage({ data }: { data: MarketsData }) {
  const W = 360;
  const x = (v: number) => 8 + v * (W - 16);
  return (
    <div className="stack">
      <h2>Feedback coverage against sales</h2>
      <p className="small muted measure">
        Share of each series' 2025 sales (ring) against its share of labelled comments (dot). No customer comments come
        from China; 7 Series feedback is almost entirely from the US.
      </p>
      <div className="row small" aria-hidden>
        <svg width={14} height={14}>
          <circle cx={7} cy={7} r={5} fill="none" stroke="var(--ink)" strokeWidth={2} />
        </svg>
        Sales share
        <svg width={14} height={14}>
          <circle cx={7} cy={7} r={5} fill="var(--data-blue)" />
        </svg>
        Feedback share
      </div>
      <div className="table-scroll">
        <table className="table">
          <thead>
            <tr>
              <th>Series</th>
              <th>Market</th>
              <th className="r">Comments</th>
              <th className="r">Sales share</th>
              <th className="r">Feedback share</th>
              <th>0% to 100%</th>
            </tr>
          </thead>
          <tbody>
            {["F70", "G60", "G70"].flatMap((model) =>
              MARKETS.map((m, i) => {
                const r = data.representativeness.find((d) => d.model === model && d.market === m);
                const sales = r?.sales_share ?? salesShare(data, model, m);
                const fb = r?.feedback_share ?? 0;
                return (
                  <tr key={model + m}>
                    <td>{i === 0 ? <strong>{MODEL_NAMES[model]} ({model})</strong> : ""}</td>
                    <td>{MARKET_NAMES[m]}</td>
                    <td className="r num">{fmtInt(r?.comments ?? 0)}</td>
                    <td className="r num">{fmtPct(sales)}</td>
                    <td className="r num">{fmtPct(fb)}</td>
                    <td>
                      <svg width={W} height={16} role="img" aria-label={`Sales share ${fmtPct(sales)}, feedback share ${fmtPct(fb)}`}>
                        <line x1={x(0)} x2={x(1)} y1={8} y2={8} stroke="var(--grid)" strokeWidth={1} />
                        <line x1={x(Math.min(sales, fb))} x2={x(Math.max(sales, fb))} y1={8} y2={8} stroke="var(--hairline-strong)" strokeWidth={2} />
                        <circle cx={x(sales)} cy={8} r={5} fill="#fff" stroke="var(--ink)" strokeWidth={2} />
                        <circle cx={x(fb)} cy={8} r={4} fill="var(--data-blue)" stroke="#fff" strokeWidth={1} />
                      </svg>
                    </td>
                  </tr>
                );
              }),
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function salesShare(data: MarketsData, model: string, market: string) {
  const group = Object.keys(GROUP_MODEL).find((g) => GROUP_MODEL[g] === model)!;
  const rows = data.sales.filter((s) => s.model_group === group && s.year === 2025);
  const total = rows.reduce((a, b) => a + b.volume, 0);
  const v = rows.find((s) => s.market === market)?.volume ?? 0;
  return total ? v / total : 0;
}

function Survey({ data }: { data: MarketsData }) {
  return (
    <div className="stack">
      <h2>Customer studies 2025</h2>
      <p className="small muted measure">
        The China study covers the 5 Series long wheelbase (G68), not the G60; the US study covers the 5 and 7 Series only.
        Survey scores measure satisfaction, so the decision engine reads a low-ranked attribute as a weakness, never as a
        market weight.
      </p>
      <div className="table-scroll">
        <table className="table">
          <thead>
            <tr>
              <th>Sheet</th>
              <th>Market</th>
              <th>Series</th>
              <th className="r">Attributes</th>
            </tr>
          </thead>
          <tbody>
            {data.survey.map((s) => (
              <tr key={s.sheet + s.market + s.model}>
                <td>{s.sheet}</td>
                <td>{MARKET_NAMES[s.market]}</td>
                <td>{s.model === "G68" ? "5 Series long wheelbase (G68)" : `${MODEL_NAMES[s.model] ?? s.model} (${s.model})`}</td>
                <td className="r num">{s.attributes}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { fmtInt, fmtNum, fmtPct, useApi } from "../api";
import type { Policy } from "../types";
import { ErrorState, Loading } from "../components/marks";

interface Variant { auc_mean: number; auc_sd: number; auc_by_fold: number[]; log_loss_mean: number }
interface EbmRun {
  n_units: number;
  n_features: number;
  complaint_rate: number;
  folds: number;
  variants: { context_only: Variant; context_plus_pdf: Variant };
  pdf_auc_gain_mean: number;
  pdf_auc_gain_by_fold: number[];
  pdf_gain_positive_folds: number;
}
interface Term { term: string; importance: number; shape: { bin: string; score: number }[] }
interface MethodData {
  classifier: Record<string, { micro_f1: number; macro_f1: number; top1_hit: number; top3_hit: number; n_comments: number; n_labels: number; majority_baseline_micro_f1: number; cross_source: { micro_f1: number; train: string; test: string }[] }>;
  n_training_comments: number;
  ablation: {
    complaint_risk_ebm: { all_features: EbmRun; linked_features_only: EbmRun; production_inputs: string[]; audit_only_inputs: string[]; global_production: Term[]; global_audit_with_pdf: Term[] };
    poor_value_check: { n_labels: number; by_sentiment: Record<string, number>; by_reason: Record<string, number>; by_fitment_tier: Record<string, number> };
    feature_classifier_fitment: {
      n_comments: number;
      n_comments_true_feature_linked: number;
      variants: Record<string, { top1_hit: number; top3_hit: number; top1_hit_linked: number; top3_hit_linked: number }>;
      car_prior_alone_top1_hit: number;
      uniform_top1_hit: number;
      mcnemar_linked: { fitment_fixes: number; fitment_breaks: number; p_value: number; significant_at_0_05: boolean };
      fitment_reranker_coefficients: Record<string, number>;
    };
  };
  tier_labels: Record<string, string>;
  quality: Record<string, any>;
  policy: Policy;
  thresholds: Record<string, number>;
}

const TASKS: Record<string, string> = { feedback_type: "Feedback type", domain: "Domain", feature: "Feature" };
const TERM_NAMES: Record<string, string> = {
  source: "Feedback channel",
  is_umbrella: "Umbrella label",
  domain: "Domain",
  market: "Market",
  engine: "Powertrain",
  model: "Series",
  fitment_tier: "Price-list fitment",
  share_standard: "Share of variants with it as standard",
  option_price_eur: "Option price (EUR)",
  option_price_pct_of_base: "Option price, % of base",
  base_price_eur: "Base price (EUR)",
};
const VARIANT_NAMES: Record<string, string> = {
  text: "Text only",
  text_plus_car_prior: "Text and the car (series, powertrain)",
  text_plus_car_prior_plus_fitment: "Text, car and price-list fitment",
};

export default function Method() {
  const { data, error, loading } = useApi<MethodData>("/api/method");
  return (
    <>
      <section className="band band--soft band--tight">
        <div className="wrap stack">
          <h1>Method and audit</h1>
          <p className="lead">
            How a recommendation is computed, how well the models work, and what the price lists did and did not change.
            Every figure on this page is read from the files written by the pipeline (reports/*.json).
          </p>
        </div>
      </section>
      <section className="band band--tight">
        <div className="wrap stack-lg">
          {loading && <Loading what="method and audit data" />}
          {error && <ErrorState message={error} />}
          {data && (
            <>
              <Scoring data={data} />
              <hr className="divider" />
              <PriceListEffect data={data} />
              <hr className="divider" />
              <Drivers data={data} />
              <hr className="divider" />
              <Classifiers data={data} />
              <hr className="divider" />
              <Quality data={data} />
            </>
          )}
        </div>
      </section>
    </>
  );
}

function Scoring({ data }: { data: MethodData }) {
  const w = data.policy.weights;
  const t = data.thresholds;
  return (
    <div className="stack">
      <h2>How a recommendation is computed</h2>
      <ol className="steps measure">
        <li>
          <strong>Feature verdict.</strong> Each comment is labelled with a feature, a reason and a type (like, defect,
          difficult to use, want). Channels differ hugely (one survey contains no praise at all), so a feature's complaints
          are compared with what its channel mix predicts: the complaint index. Small features are pulled toward their
          domain (prior strength {fmtNum(t.prior_strength, 0)}). Bad needs index ≥ {fmtNum(t.bad_index)} with the 95% interval above 1;
          good needs ≤ {fmtNum(t.good_index)} with the interval below 1. Fewer than {t.min_mentions} comments: not enough data.
        </li>
        <li>
          <strong>Four signals per series and market</strong>, each between 0 and 1: complaints (the verdict in that market),
          breadth (how many of the series' customers raise it), requests (unmet needs) and survey weakness (how low the
          matching study attribute ranks).
        </li>
        <li>
          <strong>Weighted score</strong> with default weights complaints {fmtNum(w.complaints)}, breadth {fmtNum(w.breadth)},
          requests {fmtNum(w.requests)}, survey {fmtNum(w.survey)}. Missing signals are left out and reported; with less
          than {fmtPct(data.policy.thresholds.min_coverage)} of the weight present there is no recommendation.
        </li>
        <li>
          <strong>Recommendation</strong>: prioritise at ≥ {fmtNum(data.policy.thresholds.prioritise)}, consider at ≥{" "}
          {fmtNum(data.policy.thresholds.consider)}, otherwise low priority. Markets without sales are marked not sold.
        </li>
        <li>
          <strong>Suggested move</strong> from the German price list: fix standard equipment, fix a paid option, consider
          making an option standard, or introduce an item another series already lists.
        </li>
      </ol>
      <p className="note">{data.policy.rationale.weights} {data.policy.rationale.borrowing}</p>
    </div>
  );
}

function PriceListEffect({ data }: { data: MethodData }) {
  const e = data.ablation.complaint_risk_ebm;
  const f = data.ablation.feature_classifier_fitment;
  const pv = data.ablation.poor_value_check;
  return (
    <div className="stack-lg">
      <div className="stack">
        <h2>What the price lists change in the models</h2>
        <p className="lead">
          Fitment and price were added to both models and tested on held-out data. They help the feature classifier a
          little and do not help predict complaints, so they drive the price ladder and the suggested move instead.
        </p>
      </div>

      <div className="two-col">
        <div className="stack">
          <h3>Complaint model (explainable boosting machine)</h3>
          <p className="small muted">
            Predicts whether a labelled mention is a complaint. Cross-validated by feature ({e.all_features.folds} folds), so
            price-list inputs cannot simply memorise a feature.
          </p>
          <table className="table">
            <thead>
              <tr>
                <th>Units evaluated</th>
                <th className="r">Context only</th>
                <th className="r">Context and price list</th>
                <th className="r">Change</th>
              </tr>
            </thead>
            <tbody>
              {(["all_features", "linked_features_only"] as const).map((k) => (
                <tr key={k}>
                  <td>
                    {k === "all_features" ? "All features" : "Features linked to the price list"}
                    <div className="caption">
                      {fmtInt(e[k].n_units)} mentions of {e[k].n_features} features
                    </div>
                  </td>
                  <td className="r num">AUC {fmtNum(e[k].variants.context_only.auc_mean, 3)}</td>
                  <td className="r num">AUC {fmtNum(e[k].variants.context_plus_pdf.auc_mean, 3)}</td>
                  <td className="r num">
                    {e[k].pdf_auc_gain_mean > 0 ? "+" : ""}
                    {fmtNum(e[k].pdf_auc_gain_mean, 4)}
                    <div className="caption">better in {e[k].pdf_gain_positive_folds} of {e[k].folds} folds</div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <p className="small">
            Decision: the production model uses context only ({e.production_inputs.map((t) => TERM_NAMES[t] ?? t).join(", ")}). The
            price-list variant is kept for audit and is never used for scores.
          </p>
          <p className="small muted">
            The direct test of price sensitivity is not possible yet: only {pv.n_labels} labels give a value reason, all of them
            requests, and {pv.by_reason["Vehicle equipment: not standard / too costly"] ?? 0} say “not standard / too costly”.
          </p>
        </div>

        <div className="stack">
          <h3>Feature classifier (which feature a comment is about)</h3>
          <p className="small muted">
            Re-ranks the top 10 text candidates for {fmtInt(f.n_comments)} comments. Linked: the {fmtInt(f.n_comments_true_feature_linked)} comments
            whose true feature has a price-list link.
          </p>
          <table className="table">
            <thead>
              <tr>
                <th>Inputs</th>
                <th className="r">Top-1</th>
                <th className="r">Top-1, linked</th>
                <th className="r">Top-3</th>
              </tr>
            </thead>
            <tbody>
              {Object.entries(f.variants).map(([k, v]) => (
                <tr key={k}>
                  <td>{VARIANT_NAMES[k] ?? k}</td>
                  <td className="r num">{fmtPct(v.top1_hit, 1)}</td>
                  <td className="r num">{fmtPct(v.top1_hit_linked, 1)}</td>
                  <td className="r num">{fmtPct(v.top3_hit, 1)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <p className="small">
            Fitment fixes {f.mcnemar_linked.fitment_fixes} and breaks {f.mcnemar_linked.fitment_breaks} linked comments (McNemar p ={" "}
            {fmtNum(f.mcnemar_linked.p_value, 4)}): a small but{" "}
            {f.mcnemar_linked.significant_at_0_05 ? "statistically significant" : "not significant"} gain. It is used when a
            comment is classified for a known car. The car alone picks the right feature {fmtPct(f.car_prior_alone_top1_hit, 1)} of the
            time (chance: {fmtPct(f.uniform_top1_hit, 1)}), but adds nothing once the text is known.
          </p>
        </div>
      </div>
    </div>
  );
}

function Drivers({ data }: { data: MethodData }) {
  const prod = data.ablation.complaint_risk_ebm.global_production;
  const audit = data.ablation.complaint_risk_ebm.global_audit_with_pdf;
  const maxImp = Math.max(...prod.map((t) => t.importance));
  const fitTerm = audit.find((t) => t.term === "fitment_tier");
  return (
    <div className="stack-lg">
      <div className="stack">
        <h2>What drives complaints</h2>
        <p className="small muted measure">
          Mean absolute contribution of each input to the complaint model's log-odds (production model, context only). The
          feedback channel matters most, which is why every verdict is channel-adjusted.
        </p>
        <table className="table bars">
          <tbody>
            {prod.map((t) => (
              <tr key={t.term}>
                <td style={{ width: 220 }}>{TERM_NAMES[t.term] ?? t.term}</td>
                <td>
                  <svg width="100%" height={14} viewBox={`0 0 400 14`} preserveAspectRatio="none" role="img" aria-label={`${TERM_NAMES[t.term]} importance ${fmtNum(t.importance, 3)}`}>
                    <rect x={0} y={3} width={(t.importance / maxImp) * 400} height={8} fill="var(--data-blue)" />
                  </svg>
                </td>
                <td className="r num small" style={{ width: 70 }}>
                  {fmtNum(t.importance, 3)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="two-col">
        {prod
          .filter((t) => ["source", "domain"].includes(t.term))
          .map((t) => (
            <Shape key={t.term} term={t} />
          ))}
      </div>
      {fitTerm && (
        <div className="stack">
          <h3>Audit only: price-list fitment in the complaint model</h3>
          <p className="small muted measure">
            Shape learned by the price-list variant. It did not improve held-out accuracy, so read it as description, not as
            an effect.
          </p>
          <Shape term={fitTerm} labels={data.tier_labels} />
        </div>
      )}
    </div>
  );
}

function Shape({ term, labels }: { term: Term; labels?: Record<string, string> }) {
  const rows = term.shape.filter((s) => !["missing", "unknown"].includes(s.bin));
  const max = Math.max(...rows.map((r) => Math.abs(r.score)), 0.01);
  const half = 150;
  return (
    <div className="stack">
      <h4>{TERM_NAMES[term.term] ?? term.term}</h4>
      <p className="caption">Contribution to complaint log-odds: right (red) raises, left (blue) lowers.</p>
      <table className="table bars">
        <tbody>
          {rows.map((r) => {
            const w = (Math.abs(r.score) / max) * (half - 4);
            return (
              <tr key={r.bin}>
                <td style={{ width: 200 }} className="small">
                  {labels?.[r.bin] ?? r.bin}
                </td>
                <td>
                  <svg width={half * 2} height={14} role="img" aria-label={`${r.bin}: ${fmtNum(r.score, 3)}`}>
                    <line x1={half} x2={half} y1={0} y2={14} stroke="var(--hairline-strong)" />
                    <rect x={r.score >= 0 ? half : half - w} y={3} width={w} height={8} fill={r.score >= 0 ? "var(--div-red-strong)" : "var(--div-blue-strong)"} />
                  </svg>
                </td>
                <td className="r num small">{r.score > 0 ? "+" : ""}{fmtNum(r.score, 2)}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

function Classifiers({ data }: { data: MethodData }) {
  return (
    <div className="stack">
      <h2>Text classifiers</h2>
      <p className="small muted measure">
        TF-IDF word and character n-grams with one-vs-rest logistic regression, trained on {fmtInt(data.n_training_comments)}{" "}
        de-duplicated labelled comments. Five-fold cross-validation; the cross-source columns train on one channel and test
        on another.
      </p>
      <div className="table-scroll">
        <table className="table">
          <thead>
            <tr>
              <th>Task</th>
              <th className="r">Labels</th>
              <th className="r">Micro-F1</th>
              <th className="r">Majority baseline</th>
              <th className="r">Macro-F1</th>
              <th className="r">Top-1</th>
              <th className="r">Top-3</th>
              <th className="r">Source A → B</th>
              <th className="r">Source B → A</th>
            </tr>
          </thead>
          <tbody>
            {Object.entries(data.classifier).map(([k, m]) => (
              <tr key={k}>
                <td>{TASKS[k] ?? k}</td>
                <td className="r num">{m.n_labels}</td>
                <td className="r num">{fmtNum(m.micro_f1, 3)}</td>
                <td className="r num">{fmtNum(m.majority_baseline_micro_f1, 3)}</td>
                <td className="r num">{fmtNum(m.macro_f1, 3)}</td>
                <td className="r num">{fmtPct(m.top1_hit, 1)}</td>
                <td className="r num">{fmtPct(m.top3_hit, 1)}</td>
                <td className="r num">{fmtNum(m.cross_source[0]?.micro_f1, 3)}</td>
                <td className="r num">{fmtNum(m.cross_source[1]?.micro_f1, 3)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function Quality({ data }: { data: MethodData }) {
  const q = data.quality;
  const v = q.option_catalog ?? {};
  const rows: [string, number | string, string][] = [
    ["Raw rows (one per label, not per comment)", q.raw_rows, `Reshaped to ${fmtInt(q.raw_unique_comments)} comments`],
    ["'no_class_found' placeholder rows", q.rows_no_class_found, "Dropped from labels"],
    ["Problem category written into Source C text", q.source_c_problem_prefix_stripped, "Prefix stripped (label leakage)"],
    ["Template sentence around Source D answers", q.source_d_template_stripped, "Template stripped"],
    ["Source B call notes cleaned of advisor text", q.source_b_comments, "Advisor sentences removed"],
    ["Feedback type missing on labelled rows", q.feedback_type_imputed_from_reason, "Imputed from the reason wording"],
    ["EV-only features labelled on combustion cars", q.ev_feature_on_ice_rows, "Flagged, not dropped"],
    ["Price-list ■/□ marks assigned to a variant", v.glyphs_assigned, `All marks on ${v.table_pages} table pages`],
    ["Option price pairs checked (gross = net × 1.19)", v.option_price_pairs_checked, `${(v.source_price_anomalies ?? []).length} printed anomaly kept as printed`],
    ["Base prices checked", v.base_prices_checked, "All pass"],
    ["Variants whose power matches the technical data", v.power_cross_checked, "All pass"],
  ];
  return (
    <div className="stack">
      <h2>Data quality and checks</h2>
      <div className="table-scroll">
        <table className="table">
          <thead>
            <tr>
              <th>Issue or check</th>
              <th className="r">Count</th>
              <th>Handling</th>
            </tr>
          </thead>
          <tbody>
            {rows.map(([a, b, c]) => (
              <tr key={a}>
                <td>{a}</td>
                <td className="r num">{typeof b === "number" ? fmtInt(b) : b ?? "–"}</td>
                <td className="small">{c}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ hero (Evaluate) */
.hero { padding: var(--s-8) 0 calc(var(--s-8) - 16px); }
.hero__title { max-width: 18ch; }
.hero__lead { margin-top: var(--s-5); }
.hero__form { display: flex; margin-top: var(--s-6); max-width: 960px; }
.hero__input { min-height: 64px; font-size: var(--fs-title-md); border: 0; padding: 18px 24px; }
.hero__input:focus { box-shadow: inset 0 0 0 2px var(--primary); border: 0; }
.hero__input::placeholder { color: var(--muted); }
.hero__btn { min-height: 64px; padding: 0 40px; }
.hero__examples { margin-top: var(--s-5); }
.hero__error { margin-top: var(--s-4); color: #ff9c94; }
@media (max-width: 640px) {
  .hero__form { flex-direction: column; }
  .hero__btn { min-height: 56px; }
}

/* ------------------------------------------------------------------ decision matrix */
.feature-block { padding-top: var(--s-6); border-top: 1px solid var(--hairline); }
.decision-grid { display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); gap: var(--s-6); align-items: start; }
@media (max-width: 1180px) { .decision-grid { grid-template-columns: 1fr; } }

.matrix { display: grid; gap: var(--s-2); overflow-x: auto; }
.matrix__row { display: contents; }
.matrix__corner { min-height: 1px; }
.matrix__colhead { display: flex; flex-direction: column; padding: 0 0 var(--s-2); border-bottom: 2px solid var(--ink); }
.matrix__code { font-weight: 700; color: var(--ink); font-size: var(--fs-title-sm); }
.matrix__rowhead { display: flex; flex-direction: column; justify-content: center; padding-right: var(--s-3); border-right: 2px solid var(--ink); }
.matrix__model { font-weight: 700; color: var(--ink); font-size: var(--fs-title-md); line-height: 1.2; }
.matrix__cell {
  text-align: left; display: flex; flex-direction: column; gap: 6px; padding: 16px; min-height: 124px;
  background: var(--canvas); border: 1px solid var(--hairline); cursor: pointer; border-radius: 0; color: var(--body);
}
.matrix__cell:hover { border-color: var(--hairline-strong); }
.matrix__cell[aria-pressed="true"] { border: 2px solid var(--primary); padding: 15px; }
.matrix__cell--inactive { background: var(--surface-soft); }
.matrix__score { font-size: var(--fs-display-sm); font-weight: 700; color: var(--ink); line-height: 1.1; margin-top: auto; }
