    [fmtInt(o.catalog.linked_features), "features linked to price lists", `${fmtInt(o.catalog.technical_values)} technical values as printed`],
  ];
  return (
    <section className="band band--tight">
      <div className="wrap stack">
        <h2>What the evidence covers</h2>
        <div className="coverage">
          {cells.map(([v, l, n]) => (
            <div key={l} className="spec">
              <p className="spec__value num">{v}</p>
              <p className="small">{l}</p>
              <p className="caption">{n}</p>
            </div>
          ))}
